INSERT INTO questions (id,version,grade,sem,subject,unit,unit_key,concept,type,text,a,b,c,d,answer,explain,source,enabled,created) VALUES ('S001','通用',6,'上','國語','詞語運用','通用｜6上｜國語｜詞語運用','成語意思','選擇','「他做事總是半途而廢」中的「半途而廢」是什麼意思？','做到一半就放棄','走路走到一半','把東西丟掉一半','只做一半的工作量','A','比喻做事不能堅持到底。','範例',1,'2026-11-05');
INSERT INTO questions (id,version,grade,sem,subject,unit,unit_key,concept,type,text,a,b,c,d,answer,explain,source,enabled,created) VALUES ('S002','通用',6,'上','國語','詞語運用','通用｜6上｜國語｜詞語運用','成語運用','選擇','下列哪一個詞語用得正確？','他的成績一落千丈，大家都很羨慕','這幅畫栩栩如生，好像真的一樣','他說話語無倫次，條理分明','比賽結果出爐，大家都忐忑不安地慶祝','B','栩栩如生：形容藝術作品逼真生動。','範例',1,'2026-11-05');
